        const breakEvenRevenue = fixed_costs / contributionMarginRatio;
        const targetUnits = (fixed_costs + target_profit) / contributionMarginPerUnit;
        const targetRevenue = (fixed_costs + target_profit) / contributionMarginRatio;
        return createSuccessResponse(`盈亏平衡分析结果：\n` +
            `固定成本：${fixed_costs.toFixed(2)}\n` +
