server.tool('review_workspace_health', 'Assess the overall health of your workspace by summarizing projects, task hierarchy, completion signals, and stored memories. Ideal for quickly understanding organization quality, identifying gaps, and deciding what to work on next across the full agentic workspace.', {
    workingDirectory: z.string().describe(getWorkingDirectoryDescription(config)),
    projectId: z.string().optional().describe('Optional project ID to focus the review on a single project'),
    includeMemories: z.boolean().optional().default(true).describe('Include memory summary signals in the workspace review'),
    includeCompletedTasks: z.boolean().optional().default(false).describe('Include completed tasks in the review summary'),
    maxItems: z.number().min(1).max(100).optional().default(25).describe('Maximum number of items to sample per section')
}, async ({ workingDirectory, projectId, includeMemories, includeCompletedTasks, maxItems }) => {
    try {
        const storage = await createStorage(workingDirectory, config);
        const memoryStorage = await createMemoryStorage(workingDirectory, config);
        const projects = await storage.getProjects();
        const selectedProjects = projectId
            ? projects.filter(project => project.id === projectId)
            : projects;
        if (projectId && selectedProjects.length === 0) {
            return {
                content: [{
                        type: 'text',
                        text: `Error: Project with ID "${projectId}" not found.`
                    }],
                isError: true
            };
        }
        const sampledProjects = selectedProjects.slice(0, maxItems);
        const projectSummaries = [];
        for (const project of sampledProjects) {
            const tasks = await storage.getTasksByProject(project.id);
            const visibleTasks = includeCompletedTasks ? tasks : tasks.filter(task => !task.completed);
            const topLevelTasks = visibleTasks.filter(task => !task.parentId).slice(0, maxItems);
            const completedCount = tasks.filter(task => task.completed).length;
            projectSummaries.push(`• ${project.name} (${project.id})\n  - Tasks: ${tasks.length}\n  - Open tasks: ${visibleTasks.length}\n  - Completed tasks: ${completedCount}\n  - Top-level tasks sampled: ${topLevelTasks.length}`);
        }
        let memorySummary = 'Memories: skipped';
        if (includeMemories) {
            const memories = await memoryStorage.listMemories({ limit: maxItems });
            memorySummary = `Memories: ${memories.length} sampled`;
        }
        const overallText = [`✅ Workspace health review complete.`, '', `Projects reviewed: ${sampledProjects.length}`, memorySummary, '', 'Project details:', ...projectSummaries.length > 0 ? projectSummaries : ['• No projects found']].join('\n');
        return {
            content: [{
                    type: 'text',
                    text: overallText
                }]
        };
    }
    catch (error) {
        return {
            content: [{
                    type: 'text',
                    text: `Error: ${error instanceof Error ? error.message : 'Unknown error'}`
                }],
            isError: true
        };
    }
});

