case 'create_bulk_slides': {
    const input = args;
    const coverTitle = input.title || input.topic;
    const coverSubtitle = input.subtitle || 'A Comprehensive Overview';
    const preserveCover = input.preserveCover === true;
    const coverAuthor = input.author;
    const clearExistingSlides = input.clearExistingSlides !== false;
    const defaultLayout = input.defaultLayout || 'default';
    if (!slidevManager.hasActiveProject()) {
        return {
            content: [
                {
                    type: 'text',
                    text: JSON.stringify({
                        success: false,
                        message: 'No active Slidev project. Please create or load one first.',
                    }, null, 2),
                },
            ],
        };
    }
    const slides = slideGenerator.generateBulkSlides(input);
    // Clear existing slides and add generated ones when requested
    if (clearExistingSlides) {
        const content = slidevManager.getSlidevContent();
        content.length = 0; // Clear array
    }
    for (const slide of slides) {
        if (slide.index === 0) {
            // Update cover slide unless preservation is requested
            if (!preserveCover) {
                await slidevManager.makeCover({
                    title: coverTitle,
                    subtitle: coverSubtitle,
                    author: coverAuthor,
                    background: slide.frontmatter?.background,
                });
            }
        }
        else {
            // Add other slides
            const slideContent = slide.content;
            const layout = slide.layout || defaultLayout;
            await slidevManager.addPage(slideContent, layout);
        }
    }
    return {
        content: [
            {
                type: 'text',
                text: JSON.stringify({
                    success: true,
                    message: `Generated ${slides.length} slides for topic: ${input.topic}`,
                    output: slides,
                    optionsApplied: {
                        preserveCover,
                        clearExistingSlides,
                        defaultLayout,
                        author: coverAuthor || null,
                    },
                }, null, 2),
            },
        ],
    };
}

