/**
 * List all available workflows
 */
listWorkflows() {
    return {
        content: [
            {
                type: 'text',
                text: JSON.stringify({
                    workflows: Object.entries(WORKFLOWS).map(([id, meta]) => ({
                        id,
                        ...meta,
                    })),
                }, null, 2),
            },
        ],
    };
}
/**
 * Inspect workflow structure without execution
 */
async inspectWorkflow(workflowName, focus, includeSchemas = false, validateDeps = true) {
    try {
        // Validate inputs
        if (!workflowName && !focus) {
            return {
                content: [
                    {
                        type: 'text',
                        text: JSON.stringify({
                            success: false,
                            error: 'Must provide either workflow name or focus area',
                            available_workflows: Object.keys(WORKFLOWS),
                            available_focus: ['security', 'quality', 'performance', 'comprehensive'],
                        }, null, 2),
                    },
                ],
                isError: true,
            };
        }
        if (focus && !isValidFocus(focus)) {
            return buildInvalidFocusResponse(focus, 'en');
        }
        // Select workflow
        const selectedWorkflow = workflowName || selectWorkflowByFocus(focus);
        const workflowMeta = WORKFLOWS[selectedWorkflow];
        if (!workflowMeta) {
            return {
                content: [
                    {
                        type: 'text',
                        text: JSON.stringify({
                            success: false,
                            error: `Unknown workflow: ${selectedWorkflow}`,
                            available_workflows: Object.keys(WORKFLOWS),
                        }, null, 2),
                    },
                ],
                isError: true,
            };
        }
        // Create pipeline to extract structure
        const pipeline = createWorkflow(selectedWorkflow, [], '.');
        const steps = pipeline['steps'] || [];
        // Build step details
        const stepDetails = steps.map((step, index) => {
            const detail = {
                index,
                name: step.name,
                mcp: step.tool,
                action: step.config?.action || 'unknown',
                params: step.config?.params || {},
                dependsOn: step.dependsOn || [],
            };
            if (includeSchemas) {
                detail['paramSchema'] = {
                    type: 'object',
                    properties: Object.keys(detail.params).reduce((acc, key) => {
                        acc[key] = { type: typeof detail.params[key] };
                        return acc;
                    }, {}),
                };
            }
            return detail;
        });
        // Validate dependencies
        const validationErrors = [];
        if (validateDeps) {
            const stepNames = new Set(steps.map(s => s.name));
            for (const step of steps) {
                if (step.dependsOn) {
                    for (const dep of step.dependsOn) {
                        if (!stepNames.has(dep)) {
                            validationErrors.push({
                                step: step.name,
                                error: `Missing dependency: ${dep}`,
                            });
                        }
                    }
                }
            }
            // Simple cycle detection
            const visited = new Set();
            const recursionStack = new Set();
            const detectCycle = (stepName) => {
                if (recursionStack.has(stepName)) {
                    return true;
                }
                if (visited.has(stepName)) {
                    return false;
                }
                visited.add(stepName);
                recursionStack.add(stepName);
                const step = steps.find(s => s.name === stepName);
                if (step?.dependsOn) {
                    for (const dep of step.dependsOn) {
                        if (detectCycle(dep)) {
                            return true;
                        }
                    }
                }
                recursionStack.delete(stepName);
                return false;
            };
            for (const step of steps) {
                if (detectCycle(step.name)) {
                    validationErrors.push({
                        step: step.name,
                        error: 'Circular dependency detected',
                    });
                    break;
                }
            }
        }
        return {
            content: [
                {
                    type: 'text',
                    text: JSON.stringify({
                        success: true,
                        workflow: {
                            id: selectedWorkflow,
                            name: workflowMeta.name,
                            description: workflowMeta.description,
                            focus: focus || null,
                        },
                        structure: {
                            totalSteps: stepDetails.length,
                            steps: stepDetails,
                        },
                        validation: {
                            enabled: validateDeps,
                            errors: validationErrors,
                            isValid: validationErrors.length === 0,
                        },
                    }, null, 2),
                },
            ],
        };
    }
    catch (error) {
        const errorMessage = getErrorMessage(error);
        return {
            content: [
                {
                    type: 'text',
                    text: JSON.stringify({
                        success: false,
                        error: errorMessage,
                    }, null, 2),
                },
            ],
            isError: true,
        };
    }
}

