async function getForecast(data) {
    // 这里可以直接调用你 Weather Server 中的相关逻辑
    // 为了方便演示，我们返回一个模拟结果
    const unit = data.unit === "F" ? "F" : "C";
    const days = typeof data.days === "number" && data.days >= 1 ? Math.floor(data.days) : 1;
    const temperature = unit === "F" ? "82.4°F" : "28°C";
    const dayText = days === 1 ? "今天" : `未来${days}天`;

    let forecastText = `模拟预报：当前位置(${data.latitude},${data.longitude})${dayText}天气晴朗，温度${temperature}。`;

    // 添加可选的湿度信息
    if (data.includeHumidity) {
        const humidity = Math.floor(Math.random() * 30) + 50; // 模拟 50-80% 湿度
        forecastText += ` 湿度：${humidity}%。`;
    }

    // 添加可选的风速信息
    if (data.windSpeed) {
        const speed = unit === "F" ? `${Math.floor(Math.random() * 10) + 5} mph` : `${Math.floor(Math.random() * 15) + 8} km/h`;
        forecastText += ` 风速：${speed}。`;
    }

    // 添加可选的降水概率信息
    if (data.precipitationChance) {
        const chance = Math.floor(Math.random() * 40) + 10; // 模拟 10-50% 降水概率
        forecastText += ` 降水概率：${chance}%。`;
    }

    return {
        content: [
            {
                type: "text",
                text: forecastText,
            },
        ],
    };
}

