// Calculate positions based on layout direction
function calculatePositions(direction, count, spacing) {
    const positions = [];
    const startX = 100;
    const startY = 100;

    for (let i = 0; i < count; i++) {
        if (direction === "LR") {
            positions.push({ x: startX + i * spacing, y: startY });
        } else if (direction === "RL") {
            positions.push({ x: startX + (count - 1 - i) * spacing, y: startY });
        } else if (direction === "TB") {
            positions.push({ x: startX, y: startY + i * spacing });
        } else if (direction === "BT") {
            positions.push({ x: startX, y: startY + (count - 1 - i) * spacing });
        }
    }

    return positions;
}

