export const gcpRunRevisionsDefinition = {
    name: 'gcp_run_revisions',
    description: 'Cloud Run 리비전 관리|revision history|rollback - Cloud Run 서비스의 모든 리비전 목록 조회 및 롤백 작업을 수행합니다. 배포 후 리비전 관리는 이 도구를 사용하세요',
