                description: '리전 (예: asia-northeast3). 기본: gcloud 설정값',
            },
            project_id: {
                type: 'string',
                description: 'GCP 프로젝트 ID (기본: 현재 설정된 프로젝트)',
            },
            action: {
                type: 'string',
                enum: ['list', 'rollback'],
                description: '작업 유형: list (리비전 목록 조회) 또는 rollback (특정 리비전으로 롤백)',
            },
            revision: {
                type: 'string',
                description: '롤백할 리비전 이름 (action=rollback일 때 필수)',
            },
            limit: {
                type: 'number',
                description: '조회할 최대 리비전 수 (기본: 10)',
            },
        },
        required: ['service', 'action'],
    },
};
export async function gcpRunRevisions(args) {
    try {
        const projectId = await getProjectId(args.project_id);
        const action = args.action || 'list';
        if (action === 'rollback') {
            if (!args.revision) {
                return {
                    content: [
                        {
                            type: 'text',
                            text: 'Error: revision parameter is required for rollback action',
                        },
                    ],
                    isError: true,
                };
            }
            let rollbackCommand = `run services update-traffic ${args.service} --to-revisions=${args.revision}=100 --project=${projectId}`;
            if (args.region) {
                rollbackCommand += ` --region=${args.region}`;
            }
            const rollbackResult = await executeGcloud(rollbackCommand, 60000);
            return {
                content: [
                    {
                        type: 'text',
                        text: `✅ Rollback successful\n\nService: ${args.service}\nRevision: ${args.revision}\nTraffic: 100%\n\n${rollbackResult.stdout || 'Rollback completed'}`,
                    },
                ],
            };
        }
        let listCommand = `run revisions list --service=${args.service} --project=${projectId} --format=json`;
        if (args.region) {
            listCommand += ` --region=${args.region}`;
        }
        if (args.limit) {
            listCommand += ` --limit=${args.limit}`;
        }
        const result = await executeGcloud(listCommand, 30000);
        let revisions = [];
        try {
            revisions = JSON.parse(result.stdout || '[]');
        }
        catch {
            revisions = [];
        }
        if (revisions.length === 0) {
            return {
                content: [
                    {
                        type: 'text',
                        text: `No revisions found for service: ${args.service}`,
                    },
                ],
            };
        }
        const formattedRevisions = revisions
            .map((rev) => {
            const name = rev.metadata?.name || 'unknown';
            const creationTime = rev.metadata?.creationTimestamp || 'N/A';
            const status = rev.status?.conditions?.find((c) => c.type === 'Ready')?.status === 'True' ? '✅ Ready' : '❌ Not Ready';
            const traffic = rev.status?.traffic || 0;
            const image = rev.spec?.containers?.[0]?.image || 'N/A';
            return `📦 ${name}\n   Status: ${status}\n   Traffic: ${traffic}%\n   Created: ${creationTime}\n   Image: ${image}`;
        })
            .join('\n\n');
        return {
            content: [
                {
                    type: 'text',
                    text: `🔄 Cloud Run Revisions for ${args.service}\n\n${formattedRevisions}\n\nTotal: ${revisions.length} revision(s)`,
                },
            ],
        };
    }
    catch (error) {
        return {
            content: [
                {
                    type: 'text',
                    text: formatError(error),
                },
            ],
            isError: true,
        };
    }
}

