diff_hunks.new_code:
// Very basic search function
async searchNodes(query, options = {}) {
    const graph = await this.loadGraph();
    const { limit, entityTypes, includeObservations = true } = options;
    // Filter entities
    let filteredEntities = graph.entities.filter(e => e.name.toLowerCase().includes(query.toLowerCase()) ||
        e.entityType.toLowerCase().includes(query.toLowerCase()) ||
        e.observations.some(o => o.toLowerCase().includes(query.toLowerCase())));
    // Apply entity type filter if specified
    if (entityTypes && entityTypes.length > 0) {
        const typeSet = new Set(entityTypes.map(t => t.toLowerCase()));
        filteredEntities = filteredEntities.filter(e => typeSet.has(e.entityType.toLowerCase()));
    }
    // Apply limit if specified
    if (limit && limit > 0) {
        filteredEntities = filteredEntities.slice(0, limit);
    }
    // Strip observations if not requested
    if (!includeObservations) {
        filteredEntities = filteredEntities.map(e => ({
            name: e.name,
            entityType: e.entityType,
            observations: []
        }));
    }
    // Create a Set of filtered entity names for quick lookup
    const filteredEntityNames = new Set(filteredEntities.map(e => e.name));
    // Filter relations to only include those between filtered entities
    const filteredRelations = graph.relations.filter(r => filteredEntityNames.has(r.from) && filteredEntityNames.has(r.to));
    const filteredGraph = {
        entities: filteredEntities,
        relations: filteredRelations,
    };
    return filteredGraph;
}

