    // Handle format option
    if (args.format === "compact") {
        result = {
            type: diagram.type,
            syntax: diagram.syntax
        };
    }

    // Handle includeExamples option
    if (args.includeExamples) {
        const examples = mermaid.getDiagramExamples(args.diagramType);
        result = {
            ...result,
            examples: examples
