    // Handle includeMetadata option
    if (args.includeMetadata) {
        result = {
            ...result,
            metadata: {
                complexity: diagram.description?.length > 200 ? "high" : "medium",
                category: diagram.type?.includes("flow") ? "flowchart" : "diagram",
                recommendedFor: `Creating ${args.diagramType} visualizations`
            }
        };
    }

    return {
        content: [{ type: "text", text: JSON.stringify(result) }]
    };
