Query types:
- 'docs': Component documentation (MDX content, examples, props, API reference)
- 'source': React/TypeScript source code implementation
- 'styles': CSS styles and BEM classes
Use cases:
- Need only docs + source (not styles): query_component_info with types=['docs','source']
- Need only styles: query_component_info with types=['styles']
- Need all three: use get_component_full instead (optimized for this)
Returns unified response with only requested sections per component.
IMPORTANT: Do NOT copy source code directly - use components via @heroui/react imports.
IMPORTANT: Do NOT mix BEM classes with React components - they are separate approaches.
Workflow: list_components → query_component_info (with specific types).`,
  async ctx(shared) {
    return {
      componentList: shared?.componentList || []
    };
  },
  exec(server, { config, name, description, ctx }) {
    const inputSchema2 = z.object({
      components: z.array(z.enum(ctx.componentList)).min(1).describe(`Array of component names from list_components (case-sensitive).\nExamples: ["Button"], ["Card", "TextField"].\nDO NOT guess names - always verify with list_components first.`),
      types: z.array(z.enum(["docs", "source", "styles"])).min(1).describe("Array of data types to fetch: 'docs', 'source', 'styles'. Example: ['docs','source'] fetches only documentation and source code."),
      format: z.enum(["markdown", "json"]).optional().describe("Output format: 'markdown' (default) or 'json'")
    });
    const handler = async ({ components, types, format = "markdown" }) => {
      try {
        const fetchPromises = [];
        const typeIndexMap = {};
        if (types.includes("docs")) {
          typeIndexMap.docs = fetchPromises.length;
          fetchPromises.push(
            fetchApi("/v1/components/docs", config.apiBaseUrl, {
              method: "POST",
              body: JSON.stringify({ components })
            }).catch((err) => { console.error("Failed to fetch docs:", err); return null; })
          );
        }
        if (types.includes("source")) {
          typeIndexMap.source = fetchPromises.length;
          fetchPromises.push(
            fetchApi("/v1/components/source", config.apiBaseUrl, {
              method: "POST",
              body: JSON.stringify({ components })
            }).catch((err) => { console.error("Failed to fetch source:", err); return null; })
          );
        }
        if (types.includes("styles")) {
          typeIndexMap.styles = fetchPromises.length;
          fetchPromises.push(
            fetchApi("/v1/components/styles", config.apiBaseUrl, {
              method: "POST",
              body: JSON.stringify({ components })
            }).catch((err) => { console.error("Failed to fetch styles:", err); return null; })
          );
        }
        const results = await Promise.all(fetchPromises);
        const docsResponse = typeIndexMap.docs !== undefined ? results[typeIndexMap.docs] : null;
        const sourceResponse = typeIndexMap.source !== undefined ? results[typeIndexMap.source] : null;
        const stylesResponse = typeIndexMap.styles !== undefined ? results[typeIndexMap.styles] : null;
        if (format === "json") {
          const jsonResults = components.map((component, index) => {
            const result = { component };
            if (docsResponse?.results?.[index]) {
              result.documentation = {
                url: docsResponse.results[index].url,
                content: docsResponse.results[index].content,
                error: docsResponse.results[index].error
              };
            }
            if (sourceResponse?.results?.[index]) {
              result.sourceCode = {
                filePath: sourceResponse.results[index].filePath,
                githubUrl: sourceResponse.results[index].githubUrl,
                code: sourceResponse.results[index].sourceCode,
                error: sourceResponse.results[index].error
              };
            }
            if (stylesResponse?.results?.[index]) {
              result.styles = {
                filePath: stylesResponse.results[index].filePath,
                githubUrl: stylesResponse.results[index].githubUrl,
                code: stylesResponse.results[index].stylesCode,
                error: stylesResponse.results[index].error
              };
            }
            return result;
          });
          return {
            content: [
              {
                type: "text",
                text: JSON.stringify({ results: jsonResults, _warning: docsResponse?._warning }, null, 2)
              }
            ]
          };
        }
        let responseText = "";
        if (docsResponse?._warning) {
          responseText += `${docsResponse._warning}\n\n`;
        }
        components.forEach((component, index) => {
          if (index > 0) responseText += "\n\n---\n\n";
          responseText += `# ${component}\n\n`;
          if (types.includes("docs") && docsResponse?.results?.[index]) {
            const docResult = docsResponse.results[index];
            if (docResult.error || !docResult.content) {
              responseText += `## Documentation\n\nError: ${docResult.error}\n`;
              if (docResult.status) responseText += `Status: ${docResult.status}\n`;
            } else {
              responseText += `## Documentation\n\n`;
              responseText += `**URL:** ${docResult.url}\n\n---\n\n`;
              responseText += docResult.content;
            }
          }
          if (types.includes("source") && sourceResponse?.results?.[index]) {
            const sourceResult = sourceResponse.results[index];
            responseText += "\n\n";
            if (sourceResult.error || !sourceResult.sourceCode) {
              responseText += `## Source Code\n\nError: ${sourceResult.error || "Source code not available"}\n`;
            } else {
              responseText += `## Source Code\n\n`;
              responseText += `**File:** \`${sourceResult.filePath}\`\n`;
              responseText += `**GitHub:** [View on GitHub](${sourceResult.githubUrl})\n\n`;
              responseText += `\`\`\`tsx\n${sourceResult.sourceCode}\n\`\`\`\n`;
            }
          }
          if (types.includes("styles") && stylesResponse?.results?.[index]) {
            const stylesResult = stylesResponse.results[index];
            responseText += "\n\n";
            if (stylesResult.error || !stylesResult.stylesCode) {
              responseText += `## Styles\n\nError: ${stylesResult.error || "Styles not available"}\n`;
            } else {
              responseText += `## Styles\n\n`;
              responseText += `**File:** \`${stylesResult.filePath}\`\n`;
              responseText += `**GitHub:** [View on GitHub](${stylesResult.githubUrl})\n\n`;
              responseText += `\`\`\`css\n${stylesResult.stylesCode}\n\`\`\`\n`;
            }
          }
        });
        return {
          content: [
            {
              type: "text",
              text: responseText
            }
          ]
        };
      } catch (error) {
        return {
          content: [
            {
              type: "text",
              text: `Error: Unable to query component information. ${error instanceof Error ? error.message : "Unknown error"}`
            }
          ]
        };
      }
    };
    server.registerTool(name, { description, inputSchema: inputSchema2.shape }, handler);
  }
};

