export async function handleBulkAPI(conn, args) {
    const { operation, objectName, jobOperation, externalIdField, jobId, records, pollInterval = 5000, maxPollAttempts = 60 } = args;
    try {
        switch (operation) {
            case 'createJob': {
                if (!jobOperation) {
                    throw new Error('jobOperation is required for createJob');
                }
                const jobInfo = {
                    object: objectName,
                    operation: jobOperation
                };
                if (jobOperation === 'upsert' && externalIdField) {
                    jobInfo.externalIdFieldName = externalIdField;
                }
                const job = conn.bulk.createJob(objectName, jobOperation, jobInfo);
                const jobDetails = await new Promise((resolve, reject) => {
                    job.on('error', reject);
                    job.open((err, jobInfo) => {
                        if (err)
                            reject(err);
                        else
                            resolve(jobInfo);
                    });
                });
                return {
                    content: [{
                            type: "text",
                            text: `Bulk job created successfully:\n` +
                                `Job ID: ${jobDetails.id}\n` +
                                `Object: ${jobDetails.object}\n` +
                                `Operation: ${jobDetails.operation}\n` +
                                `State: ${jobDetails.state}\n\n` +
                                `Next step: Use uploadData operation with this jobId to upload records.`
                        }],
                    isError: false
                };
            }
            case 'uploadData': {
                if (!jobId || !records || !Array.isArray(records)) {
                    throw new Error('jobId and records array are required for uploadData');
                }
                if (records.length === 0) {
                    throw new Error('records array cannot be empty');
                }
                if (records.length > 10000) {
                    throw new Error('Maximum 10,000 records allowed per upload');
                }
                const job = conn.bulk.job(jobId);
                const batch = job.createBatch();
                const batchInfo = await new Promise((resolve, reject) => {
                    batch.execute(records);
                    batch.on('error', reject);
                    batch.on('queue', (batchInfo) => resolve(batchInfo));
                });
                await new Promise((resolve, reject) => {
                    job.close((err) => {
                        if (err)
                            reject(err);
                        else
                            resolve();
                    });
                });
                return {
                    content: [{
                            type: "text",
                            text: `Data uploaded successfully:\n` +
                                `Job ID: ${jobId}\n` +
                                `Batch ID: ${batchInfo.id}\n` +
                                `Records uploaded: ${records.length}\n` +
                                `State: ${batchInfo.state}\n\n` +
                                `Job has been closed and is processing.\n` +
                                `Use getJobStatus operation to monitor progress.`
                        }],
                    isError: false
                };
            }
            case 'getJobStatus': {
                if (!jobId) {
                    throw new Error('jobId is required for getJobStatus');
                }
                const job = conn.bulk.job(jobId);
                let attempts = 0;
                let jobInfo;
                while (attempts < maxPollAttempts) {
                    jobInfo = await new Promise((resolve, reject) => {
                        job.check((err, info) => {
                            if (err)
                                reject(err);
                            else
                                resolve(info);
                        });
                    });
