                        break;
                    }
                    attempts++;
                    if (attempts < maxPollAttempts) {
                        await new Promise(resolve => setTimeout(resolve, pollInterval));
                    }
                }
                const statusText = `Job Status:\n` +
                    `Job ID: ${jobInfo.id}\n` +
                    `Object: ${jobInfo.object}\n` +
                    `Operation: ${jobInfo.operation}\n` +
                    `State: ${jobInfo.state}\n` +
                    `Records Processed: ${jobInfo.numberRecordsProcessed || 0}\n` +
                    `Records Failed: ${jobInfo.numberRecordsFailed || 0}\n` +
                    `Total Batches: ${jobInfo.numberBatchesTotal || 0}\n` +
                    `Batches Completed: ${jobInfo.numberBatchesCompleted || 0}\n` +
                    `Batches Failed: ${jobInfo.numberBatchesFailed || 0}\n\n` +
                    (jobInfo.state === 'Completed'
                        ? `Job completed successfully. Use getJobResults to retrieve results.`
                        : jobInfo.state === 'Failed'
                            ? `Job failed. Use getJobResults to see error details.`
                            : jobInfo.state === 'Aborted'
                                ? `Job was aborted.`
                                : `Job is still processing (attempt ${attempts}/${maxPollAttempts}).`);
                return {
                    content: [{ type: "text", text: statusText }],
                    isError: false
                };
            }
            case 'getJobResults': {
                if (!jobId) {
                    throw new Error('jobId is required for getJobResults');
                }
                const job = conn.bulk.job(jobId);
                const batches = await new Promise((resolve, reject) => {
                    job.list((err, batches) => {
                        if (err)
                            reject(err);
                        else
                            resolve(batches);
                    });
                });
                let allResults = [];
                let allFailures = [];
                for (const batchInfo of batches) {
                    const batch = job.batch(batchInfo.id);
                    const results = await new Promise((resolve, reject) => {
                        batch.retrieve((err, results) => {
                            if (err)
                                reject(err);
                            else
                                resolve(results);
                        });
                    });
                    const resultsArray = Array.isArray(results) ? results : [results];
                    const successful = resultsArray.filter(r => r.success);
                    const failed = resultsArray.filter(r => !r.success);
                    allResults = allResults.concat(successful);
                    allFailures = allFailures.concat(failed);
                }
                let resultText = `Job Results:\n` +
                    `Job ID: ${jobId}\n` +
                    `Total Successful: ${allResults.length}\n` +
                    `Total Failed: ${allFailures.length}\n\n`;
                if (allResults.length > 0) {
                    resultText += `Successful Records (showing first 10):\n`;
                    allResults.slice(0, 10).forEach((result, idx) => {
                        resultText += `  ${idx + 1}. ID: ${result.id}\n`;
                    });
                    resultText += `\n`;
                }
                if (allFailures.length > 0) {
                    resultText += `Failed Records:\n`;
                    allFailures.forEach((result, idx) => {
                        const errors = Array.isArray(result.errors) ? result.errors.join(', ') : result.errors;
                        resultText += `  ${idx + 1}. Error: ${errors}\n`;
                    });
                }
                return {
                    content: [{ type: "text", text: resultText }],
                    isError: false
                };
            }
            case 'abortJob': {
                if (!jobId) {
                    throw new Error('jobId is required for abortJob');
                }
                const job = conn.bulk.job(jobId);
                const jobInfo = await new Promise((resolve, reject) => {
                    job.abort((err, info) => {
                        if (err)
                            reject(err);
                        else
                            resolve(info);
                    });
                });
                return {
                    content: [{
                            type: "text",
                            text: `Job aborted successfully:\n` +
                                `Job ID: ${jobInfo.id}\n` +
                                `State: ${jobInfo.state}`
                        }],
                    isError: false
                };
            }
            case 'deleteJob': {
                if (!jobId) {
                    throw new Error('jobId is required for deleteJob');
                }
                await conn.request({
                    method: 'DELETE',
                    url: `/services/async/${conn.version}/job/${jobId}`
                });
                return {
                    content: [{
                            type: "text",
                            text: `Job deleted successfully:\nJob ID: ${jobId}`
                        }],
                    isError: false
                };
            }
            case 'listJobs': {
                const jobs = await conn.bulk.jobs();
                let jobList = `Recent Bulk Jobs:\n\n`;
                jobs.forEach((job, idx) => {
                    jobList += `${idx + 1}. Job ID: ${job.id}\n` +
                        `   Object: ${job.object}\n` +
                        `   Operation: ${job.operation}\n` +
                        `   State: ${job.state}\n` +
                        `   Created: ${job.createdDate}\n\n`;
                });
                return {
                    content: [{ type: "text", text: jobList }],
                    isError: false
                };
            }
            default:
                throw new Error(`Unknown bulk operation: ${operation}`);
        }
    }
    catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        return {
            content: [{
                    type: "text",
                    text: `Error executing bulk API operation: ${errorMessage}`
                }],
            isError: true
        };
    }
}

