        candidates = candidates.filter(p => p.price <= budget);
    }
    if (candidates.length === 0) {
        candidates = [...PRODUCTS].sort((a, b) => a.price - b.price);
    }
    const normalizedTemperature = String(temperature || "任意");
    const normalizedMilkPreference = String(milkPreference || "任意");
    let ranked = candidates.map(product => {
        let score = 0;
        const isHotSpec = product.specs.some(spec => spec.includes("热"));
        const isIceSpec = product.specs.some(spec => spec.includes("冰"));
        if (normalizedTemperature === "热" && isHotSpec)
            score += 3;
        if (normalizedTemperature === "冰" && isIceSpec)
            score += 3;
        if (normalizedTemperature === "任意")
            score += 1;
        if (normalizedMilkPreference === "喜欢奶味" && (product.name.includes("拿铁") || product.name.includes("卡布")))
            score += 3;
        if (normalizedMilkPreference === "不加奶" && product.name.includes("美式"))
            score += 3;
        if (normalizedMilkPreference === "任意")
            score += 1;
        if (preference.includes("浓郁") && (product.name.includes("拿铁") || product.name.includes("卡布")))
            score += 2;
        if (preference.includes("清爽") && product.name.includes("美式"))
            score += 2;
        if (preference.includes("平衡") && product.name.includes("拿铁"))
            score += 1;
        if (preference.includes("顺滑") && product.name.includes("卡布"))
            score += 2;
        return { product, score };
    }).sort((a, b) => b.score - a.score || a.product.price - b.product.price);
    const best = ranked[0] ? ranked[0].product : PRODUCTS[0];
    const suggestedSpec = best.specs.includes("大杯/热") ? "大杯/热" : best.specs[0];
    let responseText = `### 咖啡推荐结果 ☕\n\n` +
        `**推荐商品**：${best.name}\n` +
        `**推荐规格**：${suggestedSpec}\n` +
        `**价格**：${best.price}元\n` +
        `**推荐理由**：${best.description}\n`;
