async findRelatedEntities(entityName, maxDepth = 1) {
    const graph = await this.loadGraph();
    const rootEntity = graph.entities.find(e => e.name === entityName);
    if (!rootEntity) {
        throw new Error(`Entity with name ${entityName} not found`);
    }
    const normalizedDepth = Math.max(1, Math.floor(maxDepth));
    const visitedEntities = new Set([entityName]);
    const visitedRelations = new Set();
    let frontier = new Set([entityName]);
    for (let depth = 0; depth < normalizedDepth; depth++) {
        const nextFrontier = new Set();
        graph.relations.forEach((relation, index) => {
            let connectedEntityName = null;
            if (frontier.has(relation.from)) {
                connectedEntityName = relation.to;
            }
            else if (frontier.has(relation.to)) {
                connectedEntityName = relation.from;
            }
            if (connectedEntityName !== null) {
                visitedRelations.add(index);
                if (!visitedEntities.has(connectedEntityName)) {
                    visitedEntities.add(connectedEntityName);
                    nextFrontier.add(connectedEntityName);
                }
            }
        });
        frontier = nextFrontier;
        if (frontier.size === 0) {
            break;
        }
    }
    return {
        rootEntity: entityName,
        maxDepth: normalizedDepth,
        entities: graph.entities.filter(e => visitedEntities.has(e.name)),
        relations: graph.relations.filter((_, index) => visitedRelations.has(index))
    };
